import json
import os

with open('c:/projects/apache/school1/src/ptable/data/cm_temp.json', 'r', encoding='utf-8') as f:
    cm_data = json.load(f)

cm_data['extract_html'] = "<p>Curium (symbol <strong>Cm</strong>, atomic number <strong>96</strong>) is a fascinating, synthetic, and highly radioactive metal. Named in honor of the pioneering scientists Marie and Pierre Curie, this element is a heavy hitter in the actinide series. It glows with a mesmerizing purple light in the dark because of its intense radioactivity. While you will not find curium naturally on Earth today, scientists have mastered the art of creating it in laboratories and nuclear reactors. It has proven incredibly valuable in space exploration, powering devices that analyze Martian rocks, and remains a proud subject of radiochemistry research around the world, including landmark achievements in India.</p>"

sections = {}

sections['History'] = "<p>Curium's story began in secret during the height of World War II. It was first synthesized in 1944 as part of the Manhattan Project by a team of brilliant scientists: Glenn T. Seaborg, Ralph A. James, and Albert Ghiorso at the University of California, Berkeley. By bombarding plutonium with alpha particles in a cyclotron, they successfully created this new element. Its discovery was closely guarded and only revealed to the public after the war in 1945 - interestingly, Seaborg first let the secret slip on a children's radio show called the <em>Quiz Kids</em>! The element was proudly named 'Curium' after Marie and Pierre Curie, matching the naming pattern of gadolinium (named after Johan Gadolin), which sits just above it on the periodic table.</p>"

sections['Characteristics'] = "<p>Curium is a hard, dense, and silvery-white metal. One of its most striking features is that it literally glows purple in the dark due to the sheer intensity of its radiation. It has a melting point of 1,340 deg C (2,444 deg F) and is chemically reactive, easily forming compounds. Curium is electropositive and typically exists in a +3 oxidation state. Because it is highly toxic and radioactive, it poses significant health risks - if absorbed into the body, it tends to accumulate in the bones, disrupting the production of red blood cells.</p>"

sections['Isotopes'] = "<p>Curium has no stable forms; all 19 of its known isotopes (from <sup>233</sup>Cm to <sup>251</sup>Cm) are radioactive. The longest-lived isotope is Curium-247, boasting a half-life of 15.6 million years! Other notable isotopes include Curium-242 and Curium-244, which are more commonly used in research and have shorter half-lives of 162.8 days and 18.1 years, respectively. Curium-250 is particularly unique because it mostly decays by spontaneously splitting apart (spontaneous fission). Many of its isotopes can sustain nuclear chain reactions, meaning they could theoretically be used as nuclear reactor fuel, though their extreme radioactivity and scarcity make this impractical today.</p>"

sections['Occurrence'] = "<p>Because even its longest-lived isotope (Curium-247) has a half-life much shorter than the age of the Earth, any primordial curium that existed when our planet formed has long since decayed away into other elements. Today, curium is almost entirely synthetic, created in small amounts in nuclear reactors or laboratories. It does occasionally appear as a byproduct in spent nuclear fuel. Historically, trace amounts of curium were also detected in the environment following atmospheric nuclear weapons testing, such as the <em>Ivy Mike</em> thermonuclear test in 1952. While natural curium does not exist on Earth, scientists believe traces of it may occasionally be brought here by cosmic rays or produced in distant stellar events.</p>"

sections['Applications'] = "<p>Despite its rarity and hazards, curium has carved out a niche in some truly out-of-this-world applications. Its most famous role is in space exploration. Curium-244 serves as the alpha particle source for Alpha Particle X-ray Spectrometers (APXS). These incredible instruments have been mounted on Mars rovers - like <em>Pathfinder</em>, <em>Spirit</em>, <em>Opportunity</em>, and <em>Curiosity</em> - to zap Martian rocks and soil, helping scientists understand their chemical composition. Thanks to the intense heat generated by its radioactivity, curium has also been studied as a power source for radioisotope thermoelectric generators (RTGs) in spacecraft. In the past, Curium-242 was even considered for powering long-lasting pacemakers before safer lithium batteries took over. In nuclear research, curium is used as a stepping stone to synthesize even heavier, undiscovered elements.</p>"

sections['Indian Context'] = "<p>India has made significant strides in the complex field of radiochemistry. A major milestone for the country occurred in December 1975, when scientists at the Bhabha Atomic Research Centre (BARC) in Trombay successfully isolated and purified Curium-242 for the very first time in India. The team achieved this by irradiating indigenously prepared Americium-241 with neutrons in the Cirus reactor. Working with highly radioactive materials required immense skill and the use of specialized glove boxes, marking a proud achievement in India's nuclear research capabilities.</p>"

cm_data['sections'] = sections

